INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `RewardText`) VALUES
(978500, 18, 3, 'Aufr... mmrg, fr glmrg mur. Mmrf au flku, mmrngk mrgfrg fr rlmmrgl. Mnlm gmrl glgk frgkm. Burglknn mrgl mmrklglm rglmmu mmr.'),
(978501, 4, 1, 'Akmug? Mrlu mrk mmrglm nglurl mrkmr. Mrlu flku rgl mmr fr ffurgmr. Mrlu flku rgl bllug... mur ffrf mrgs.'),
(978502, 1, 36, '5. Vrum Ruftos, Vrum Engoth. Noth. Ruftvess Ash Uden, Gloin. Ash Uden Ko Agol Regenthor Hir.'),
(978503, 1, 61, '1, 2, 3... 8. Nud 8. Ruff Ash Algos. Lon Thor Ver... Thor Ver E Novas Vrum.'),
(978504, 11, 20, 'Flgrgrr. Rl. Mmrf au bu. Mmrf au bu! Mmm glgk mm. Mr mm flkmmm bu. Mr mm flkmmm mrrgluflm.'),
(978505, 1, 0, 'Fl. 10. ...Afrm. Ffll.'),
(978506, 1, 2, '6. Mmmm. Aaglm mrfrfl nakm amrgk... amrgk... bmrll nnlmrm frglmur. Fl\'mrg mrngmm au glgk mrkmr. Mrrr mrngmm au glgk mrkmr.'),
(978507, 2, 0, 'Mrgs mrn bmrll uagf. ...Na ugrgm rglll mrgl fr uagf rlm mr mr mur. Fl. Frmrm glgk fflk. Mrfr rmmr rfr. Fff nl\'mrg.'),
(978508, 1, 273, 'Mmmm, mmmm. Mmm mmrgf frgkm. ...Mr aurlm aumrmmrg mrgklg rlm flku. Bmm mngr Mr rmmr mrgklg rrfrr rlm mrgs.'),
(978509, 11, 1, 'Mr mrgllu fr Brglum shng mrflg mrgmrfur gmrl glgk ffffr. Mrg fr. Urg amrlm mrfrg mmmrrglg mrgs rglmm.'),
(978510, 1, 0, 'An Valesh. Nevren. Ash Vrum Dana Forthis, Lon Lars Ko Vandar.'),
(978511, 1, 2, 'Mrgl... mmmrna. Mrrr n aafl.'),
(978512, 274, 25, 'Mrgl. Mrgl. Mmrf. Mmrf mmr Mr skl, hrgmrgl glgk mrglu mur\'hr affrr...'),
(978513, 4, 17, '8! 8 gluglm! Aufr, flku furglmumrl, furglmumrl fuaffr. Mrrr frgll mrfrfl mr ffrf nglurl urlgl. Mrrr!'),
(978514, 66, 23, 'Mmmm! Mmmm. Mmrglmm gklmr huag mmrgf mnlurlg. Mrgs mmmmr frknnn mrngk mmmr. Mr akmrg fr rklm rlm frfll glmurg.'),
(978515, 21, 1, 'Mrfr furglmm flku. Mmrg! Mrfr frflmrg mrgmuflglu mmmr. Glmm nglurl gllugk mrkumr, fffrgrr.'),
(978516, 11, 20, 'Frgll mmr mmr. Frgll! Mrglm mur flku rgmmrg. Mr mm gf mmmrl ffrf huuff. Mrglm mur mrgl mmrgk.'),
(978517, 2, 1, 'Mmrgrg rmmr ff. Mmrgrg rmmr rff gmuffrg gluglm mmnlugmmr, n flku rmmr mnna gluglm mmnlugmmr. Fff mrgl glgk glmrlu.'),
(978518, 51, 1, 'Uglmr. Aaaaa mrfrfl. Frgmr? Murl, frgl. Klrkm, aknlmrg. Mrlu mrk mmrglm nglurl mrg, glmrf glg glgk mrglu amr mrkm\'mrg.'),
(978519, 21, 51, '3 hmr! N flku naagl amrlm mm nglurl ffum. Gfffrgm mrngk mmmr. Mrgklm frknnn mrngk mmmr.'),
(978520, 2, 18, 'Fl. Fl. Flg ffffl flku bmrll mrgkm? Rrg bu\'hr mmrgk. Na mmmurlok mrglgl fr mrgkm mrgl aurgkmu. Mrlmrg mrgl mmr aurgkmu. Glmm km.'),
(978521, 15, 0, '...'),
(978522, 5, 1, 'Mrgs skl bu. Mrgs Aaag bu. Mr mrkm... n glgk mrglu mur mmmrglm bu. Mrgm mmmrl. Mrgm mmmrl! ...Aufr, ngll mrgl flmrr.'),
(978523, 1, 0, 'Mmrf.'),
(978524, 1, 61, 'Ruff. Ash Dyrstigost Ewiddan. Wirsh... Ko. Ko Vandarwos. Ash Nandige Ver Borne Daegil. Noth Daegil. Dana. O Vohl. Ash Nud Bur. O Faergas Vohl.'),
(978525, 11, 4, 'Frglg mnnnlm! Frgll! Mrgl! Mmm glgk mm. Mr mm rmmr rgmmrg mrfrfl mnnn glgk glmrgs aau mrmrg mrfrfl.'),
(978526, 273, 17, '5! Mmm glgk ffrnng. Klm mmrglm mrfrfl, aumrgm, aumrgm. Mrfr rmmr rgmmrg. Mrgs rgmmrg glr. Ammmmrg mmmr.'),
(978527, 66, 273, 'Mrkugmrgk n mrlu. Fl. Fl! Rrg glgk ffl mrgrg rff mrlmmrll. Rrg glgk bbrg mrgl rrfrr naurgkl, n aau amrlm fr mrglglm mrfl.'),
(978528, 4, 94, 'Mrgs brlm! Mrgs brlm flku brlm flku brlm! N Ammmmmr! Mugl! Augflu! ...Mrlu mmr? Furglk glm mrk mrgluag glm?'),
(978529, 18, 1, 'Mrgk-mnnnlu. Aufr... mmrg, mrglglm mur. Ffl ffrrg mrrgll? Mr mrglu amr. Frrgkm glgk mrglu amr. Afrm. Ffll. Burglknn mrgl mmrklglm mrgl ffr glugl.'),
(978530, 1, 273, 'Bmm rlm glgk frgkm. Bmm rlm glgk frgkm. Bmm rlm glgk frgkm... n mrrgll mur? Mrglm mur mrgl mmrgk. Burglknn mrgl bu. Burglknn. Mrgm rlmrg gluglm.'),
(978531, 4, 94, 'Mmrgrg mrgfrg mrgs! Mmrgrg Frglr mrgs! Urgknng ffffl flku fr mrgkm? Urgknng frflmrg glur glkmng. Mrrr rlmrg!'),
(978532, 273, 1, 'Mmrgrg rmmr mmmrna mrlu. Mmrlugl fffrgrr mmmrna mrlu... mmrgl mmr hurlk. Mugmu aau aaflua.'),
(978533, 4, 11, 'Mn Flmrg! Mmrf au mmmr! Mmrf mr murg Mr gs! Mmrf mr... hmrfrg ffrrg mrrgluflm fur? Mrgl mrgl bu frglmr?'),
(978534, 4, 1, 'Mmrlmmrna... mrglgl... mmrl rgklmr. Ffllm, frgl, glglmm. Ffllm, frgl, glglmm. Na mgrrrl! Na mgrrrl mmgr nk fl mrgl bu!'),
(978535, 16, 1, 'Al Anu Shando Mush No Anu Shar Tal Dieb. N Da Dorithur. An Ethala Alah\'ni Fal Aman Shano... N Ishnu O Aman Ash Neph\'o Dur No Do\'rah. Anu Dieb Do\'rah.'),
(978536, 16, 2, 'Dorithur... Bandu Al Alah. Aman Ala Alah Aman. Dor Ash Ni, Dor Ash Anu. Fal Eburi Shar Aman\'ni Do Diel. O Belore Dath O Banthalos.'),
(978537, 273, 0, 'Mmmm. Mrlu glgk skmur mrgl flglr. Mrlu flglm ffrf flku mrgrg fuf mrkmrl.'),
(978538, 4, 11, 'Mr agffr! Mr agffr mrgs mrlmmrk mrgs mmgr! Murrglm. Murrglm mrrgll...'),
(978539, 11, 4, 'Frgll! Mmrf au bu! Fff mrgl flku! Mrnlll frgkn... mmrgl flku! Mr ffr brnnl bu shrlr. Na. Nk, ff. Mmrg. Na mrgl ffurgs.'),
(978540, 4, 94, 'Flg grgrglrg! Mr mrglglm flug-gffrg grgrglrg au glgk ffffr! Mr mrgs! Frglmr ffrf au mrgs!'),
(978541, 11, 21, 'Flgrgrr. Mrfr\'hr mnnaaaag mrngk mmmr. Mrfr\'hr mnnaaaag mrngk Mrgmn. Mr glgk brnnl, flmurg ng nglurl mrkmr. Mr brnnl mrgl mrnngl mmmm.'),
(978542, 6, 18, 'Mrmrr. Mrglm mrgluag. Mrgm rlm aaflua, mmr rlm mmmmmr... rlm mrgs. Mrgl glm flug-mrffl mmmr mrgluag? Furglk glm mrk flmrf?'),
(978543, 20, 1, '5... 5 brlm mmrgrk. Flglu mmmr nglurl rlglu. Ngl. Uglmr. Uglmr.'),
(978544, 5, 25, 'Mrmrkm. Mr glmrgfr rgl flug. Mmrn glmrgfr. Gmrg frgl glgk glmrgfr, mmmrrglg uaa. Ffflufrgm mr. Ffflufrgm mmrklglm.'),
(978545, 11, 1, 'Mr mmrgr... mrgl aknlmrg fr klllufr. Mrlg fffr flku ffr. Mrlg fffr fr mr ffrf rglklurg. Afrm. Gfffrgm mrngk fr mmrgr.'),
(978546, 11, 23, 'Mr nl. Gklmrgkl. ...Mrgs fflmm murflu. Mnlmrgl mrngk frlmm. Fl\'mrg rglrrr frlmm.'),
(978547, 5, 25, 'Fflmmrg? Rglmmu amr mrgl glgk ffffr, mmrlgrr mmr? Kl ffr glugl? Kl Murl glugl?'),
(978548, 4, 1, '...Mmrgrg\'mmur kmnlmm. Mmrgrg\'mmur Hmrlgl! Mrgkl ngll? Fff mrgl glgk glugl. Fff mrgl ffr nglg glugl, n bu mrgl naagl mmr.'),
(978549, 11, 4, 'Flg mrfr, n flku ffffl bu mrlu? Bu! Mrlu mrgs rmmr mrgluugl flku mrglglrmn. Fflmnnnlmm. Mmmr glgk ammr glklrlk.'),
(978550, 274, 11, 'Mr rnlkm. Glr. Mr frgrlurr rgl mrgrmu mmrl, Mr hmmmmrlm... n mrk rgl mmr srgrg mrrnnam bu. Aaglm bu mmmrg. Nk, mmmrg. Frgk mrk mrgrg aafl bu.'),
(978551, 2, 66, 'Anar Bandu. O Ash\'therod Adore... N Talah Diel Lo Eburi. Ala Anu Osa. Andu Alah\'ni Aman, Tal Anu Dath.'),
(978552, 273, 1, 'Aurl! N glgk flug-mrffl amrlm mmmmmr. Mmua. Mmua mrgl mr mrk mrgluag glm rglklurg.'),
(978553, 274, 273, 'Aurl mrgl aurgllr, n glgk fl mrlug mmnlr flmrf. Gmrg glgk flug-mrffl rmmr mmmrmurr, mrglglm mur. Mmrn-mrffl fffrgrr mmmrmurr.'),
(978554, 11, 23, 'Aaaaa naagl. Aaaaa Frfffl. Uglmr! Naaaur! Mmumr, mmmrna mmr, nglurl rrgrg... mumrl naagl...'),
(978555, 4, 1, 'Mr fur mmrgr. Mrgl aaflua mrgl glgk fur mmrgr! Rrg aau fur. Mrmrglg. Kl glgk glu. Kl mrlmmm mrfrfl mmrgrk.'),
(978556, 4, 25, 'Mrgs brlm! Mmgr flmrglmrm! Mr glu rgl bllug mmmrg, mrgk glgk amrglug. Flmrrr. Mr mrgrg fflm glgk rkmrgk... Mr mrgrg fflm glgk rkmrgk.');
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`) VALUES
(978500, 1, 6, 'Mr mmrlgl, mrglglm mur. Mr mmrlgl.'),
(978501, 1, 6, 'Mrg flku mrl glmrrfl? Mmmr 4?'),
(978502, 1, 6, 'Lo Agol Gloin. Hir.'),
(978503, 1, 6, 'E Garde 0. Ras Se E Garde 0?'),
(978504, 1, 6, 'Mmrgkl? Muflm mmmr glgk hrgllm.'),
(978505, 1, 6, '...'),
(978506, 1, 6, 'Frglur. Mr Glg\'hr mrkmr mmnlrg fr nnlmrm. Na gl mur.'),
(978507, 1, 6, 'Mrkmu.'),
(978508, 1, 6, 'Mr frgkm mrgl mmrlmrg n glgk Mrlmmrgl rgl mmrklglm. Mrgm fr mmmm rklm.'),
(978509, 1, 6, 'Furglk aaflua? Uglmr mrgl nk aaflua.'),
(978510, 1, 6, 'Garde Borne. Garde Borne, Gloin.'),
(978511, 1, 6, 'Ffr amr. Mrkn, mrmmm mrk mmr.'),
(978512, 1, 6, 'Mrgl? Mrgs mrlrmm\'mrg bbrllg mmmr! Frgll!'),
(978513, 1, 6, 'Mmua akngf? Mrglm Hmrmrl?'),
(978514, 1, 6, 'Aaaam. N mrglu fr Brglum mrlg, flku rgl frfflmrlkl. Mrgs rgl fffrgrr frfflmrlkl.'),
(978515, 1, 6, 'Mmurlmmr. Mmurlmmr mrngk ngll.'),
(978516, 1, 6, 'Mrg mrgs aafl flku? Flg mrlrmm\'mrg aafl flku. Mrg mrgs?'),
(978517, 1, 6, 'Mrg mrk fuf ff? Glmrn blrlmr mrk fuf ff.'),
(978518, 1, 6, 'Mr aknl mrgl rglmmrlg. Mr frnnaau mrgl mmr.'),
(978519, 1, 6, 'Mrg flku glmrgl mrfrfl? Mr ffrrg mrk glmrgl flku?'),
(978520, 1, 6, 'Mrg flku mrgl mmgr km?'),
(978521, 1, 6, 'Mmrglmm murkmrr, mrglglm mur.'),
(978522, 1, 6, 'Mrgrrgl. Mrgrrgl!'),
(978523, 1, 6, 'Mrgl mrgrrrlk mrgmrg.'),
(978524, 1, 6, 'Ve Ewiddan? Nagan Ewiddan? Ti.'),
(978525, 1, 6, 'Mr. Fr.'),
(978526, 1, 6, 'Mmur... frlu... rgl flku frngk? Mr gs mrkurlm mr ffrf mm.'),
(978527, 1, 6, 'Mrkmrr mrkmurlua? Mr mmr kmnlmm frl?'),
(978528, 1, 6, 'Fl!'),
(978529, 1, 6, 'Ffl mrmurnl mugshr ffr glugl? Mnlmrgl. Frg mmmr aafl flku.'),
(978530, 1, 6, 'Ffll, mrglglm mur. Afrm. Frgk Mr mrgrg aafl.'),
(978531, 1, 6, 'Aaurgr mmugl. Aaurgr mrflg mmugl.'),
(978532, 1, 6, 'Rg mrk kmnlmm? Mr naagl fflm mrfrfl.'),
(978533, 1, 6, 'Mrkuu? Mrkuu? Fr bu fr mmm frl?'),
(978534, 1, 6, 'Mr aaflua brlmrr mrkmrl. Mmur, aaflua. Mmurgm, aaflua.'),
(978535, 1, 6, 'Anu Mush Anar. N Talah Anu Eburi.'),
(978536, 1, 6, 'Ala Anu Diel Lo? Lo Shan\'re Anu Shari\'fal. Anu Shando Rini Lo.'),
(978537, 1, 6, 'Mr furlgl naagl auurr ffrf mrfrfl.'),
(978538, 1, 6, 'Mrg mrgs mmmrna? Fr mrgs kmnlmm? Glg Mr mmmrna mr mmrl?'),
(978539, 1, 6, 'Fflmr mrgluag rgl hmmr mrgluag. Mrgl.'),
(978540, 1, 6, 'Mrg mrgs bbrllg bu? Mrg mrgs murlm?'),
(978541, 1, 6, 'Mrglm gl. Frknnnngl. Murg gl.'),
(978542, 1, 6, 'Mrg flku aafl? Mrg flku aafl mmr mrk agmmr?'),
(978543, 1, 6, 'Mmua akngf brlm mmrgrk? Hmmrlmr mrfrfl rlm mmmr.'),
(978544, 1, 6, 'Mr ngl, mrglglm mur. Mr glmrgfr.'),
(978545, 1, 6, 'Nlmrgl! Mrlg mrgl amrflm! Mrlg mrgl fffrgrr amrflm!'),
(978546, 1, 6, 'Rfrg. Mrg amrgk. Rg flku mrluammr hrlg mrlurmr?'),
(978547, 1, 6, 'Mrg glgk gmrm mrl bbmrklua? Mrfr frmrgrlm fffr glmrgmr.'),
(978548, 1, 6, 'Aaaaa glgk ffffr! Aaaaa bu!'),
(978549, 1, 6, 'Fr mrgs ffflmrr? Gsrlugmr mmrgm\'mrg shrkm. Brlmr km shrkm.'),
(978550, 1, 6, 'Furglk mrgl ngll? Frgk ffrrg flku... mmrg. Aufr, Mmumr.'),
(978551, 1, 6, 'Fulo Anoduna. Thoribas Lo.'),
(978552, 1, 6, 'Na mrkm rlm hmm, mrglglm mur. Flm rgl mmr mrglu amr.'),
(978553, 1, 6, 'Frgk ffrrg mrrgll aurgllr mmmrna mrglm? ...Nk. Fl\'mrg rglrrr mmmr.'),
(978554, 1, 6, 'Umrmr mmnlrg ffum. Mrgm mrmrg gluurgkmr. Mmrrglmrff mrmrg ng rff... mmmrlu mmmmm.'),
(978555, 1, 6, 'Mrgrl aaflua, mrglglm mur. Mmrgrg mmrgr?'),
(978556, 1, 6, 'Afrm! Afrm! Ffllm mmr!');
